"""J4 attack (i): extract every sentence of the three version-4 files that
contains NEG, floor, LEAD, reach, ceiling, stake, below, rho, exponent,
capacity or 13-bit. Prose = every YAML string scalar outside code_blocks[].code
and outside verbatim relay outputs; code = docstrings and comments of the
fourteen code blocks; verbatim = the embedded relay outputs (machine text).
Deterministic; no randomness."""
import re, sys, json, yaml, io, tokenize, hashlib

ROOT = "/home/user/crypto-autoresearcher/"
FILES = {
    "H": "ledger/hypotheses/H-BINSTD-9b29a0.yaml",
    "E": "experiments/EXP-BINSTD-811a2e/specification.yaml",
    "A": "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-d08b44/design/TASK-20261002-f48089/proof-search-map-audit.yaml",
}
KW = [
    ("NEG", re.compile(r"\bNEG")),
    ("floor", re.compile(r"floor", re.I)),
    ("LEAD", re.compile(r"\blead\b|\bLEAD", re.I)),
    ("reach", re.compile(r"\breach", re.I)),
    ("ceiling", re.compile(r"\bceiling", re.I)),
    ("stake", re.compile(r"\bstake", re.I)),
    ("below", re.compile(r"\bbelow\b", re.I)),
    ("rho", re.compile(r"\brho\b", re.I)),
    ("exponent", re.compile(r"\bexponent", re.I)),
    ("capacity", re.compile(r"\bcapacity", re.I)),
    ("13-bit", re.compile(r"13[- ]bit", re.I)),
]
VERBATIM_KEYS = {"output", "output_verbatim", "output_summary_verbatim", "text", "summary_as_relayed", "command", "parse_output"}

ABBR = re.compile(r"(?:\be\.g|\bi\.e|\bet al|\bvs|\bcf|\bSec|\bFig|\bno|\bEq)\.$", re.I)

def split_sentences(s):
    s = " ".join(s.split())
    out, start = [], 0
    for m in re.finditer(r"[.?!](?=\s+[A-Z0-9(\"'\[])|;(?=\s)|\s-\s(?=[A-Z])", s):
        end = m.end()
        piece = s[start:end].strip()
        if m.group(0) == "." and ABBR.search(s[start:end]):
            continue
        # keep decimals and version numbers intact: '.' followed by space then digit after a digit? accept
        if piece:
            out.append(piece)
        start = end
    tail = s[start:].strip()
    if tail:
        out.append(tail)
    return out

def walk(node, path, sink):
    if isinstance(node, dict):
        for k, v in node.items():
            walk(v, path + [str(k)], sink)
    elif isinstance(node, list):
        for i, v in enumerate(node):
            walk(v, path + [str(i)], sink)
    elif isinstance(node, str):
        sink.append((path, node))
    elif node is not None and not isinstance(node, (bool, int, float)):
        sink.append((path, str(node)))

def code_text_units(code):
    units = []
    try:
        toks = list(tokenize.generate_tokens(io.StringIO(code).readline))
    except tokenize.TokenError:
        return units
    prev = None
    for t in toks:
        if t.type == tokenize.COMMENT:
            units.append(("comment", t.start[0], t.string.lstrip("#").strip()))
        elif t.type == tokenize.STRING and (prev is None or prev.type in (tokenize.INDENT, tokenize.NEWLINE, tokenize.NL, tokenize.DEDENT)) and t.string.startswith(('"""', "'''")):
            units.append(("docstring", t.start[0], t.string.strip('"\'')))
        if t.type not in (tokenize.NL, tokenize.COMMENT):
            prev = t
    return units

rows = []
for tag, rel in FILES.items():
    raw = open(ROOT + rel, "rb").read()
    d = yaml.safe_load(raw)
    text = raw.decode("utf-8")
    # header comments (YAML comments are part of the file's sentences)
    lines = text.split("\n")
    comment_block, cstart = [], None
    def flush(cb, cs):
        if cb:
            for sent in split_sentences(" ".join(cb)):
                hits = [k for k, rx in KW if rx.search(sent)]
                if hits:
                    rows.append({"file": tag, "kind": "yaml-comment", "path": "#comment@L%d" % cs, "kw": hits, "sentence": sent})
    for i, ln in enumerate(lines, 1):
        st = ln.strip()
        if st.startswith("#"):
            if cstart is None:
                cstart = i
            comment_block.append(st.lstrip("#").strip().strip("=").strip())
        else:
            flush(comment_block, cstart)
            comment_block, cstart = [], None
    flush(comment_block, cstart)
    sink = []
    walk(d, [], sink)
    for path, s in sink:
        p = "/".join(path)
        if tag == "A" and len(path) >= 4 and path[1] == "code_blocks" and path[-1] == "code":
            cid = d["proof_search_map_audit"]["code_blocks"][int(path[2])]["id"]
            for kind, ln, u in code_text_units(s):
                for sent in split_sentences(u):
                    hits = [k for k, rx in KW if rx.search(sent)]
                    if hits:
                        rows.append({"file": tag, "kind": "code-" + kind, "path": "%s@codeline%d" % (cid, ln), "kw": hits, "sentence": sent})
            continue
        kind = "verbatim" if ((path[-1] in VERBATIM_KEYS and not (path[-1] == "text" and "outputs_verbatim" not in path)) or "output" in path[-1]) else "prose"
        if kind == "verbatim":
            hits = [k for k, rx in KW if rx.search(s)]
            if hits:
                rows.append({"file": tag, "kind": "verbatim", "path": p, "kw": hits, "sentence": "<verbatim relay text, %d chars, sha256 %s>" % (len(s), hashlib.sha256(s.encode()).hexdigest()[:16])})
            continue
        for sent in split_sentences(s):
            hits = [k for k, rx in KW if rx.search(sent)]
            if hits:
                rows.append({"file": tag, "kind": kind, "path": p, "kw": hits, "sentence": sent})
for i, r in enumerate(rows, 1):
    r["id"] = "S%04d" % i
json.dump(rows, open(sys.argv[1], "w"), indent=1)
from collections import Counter
print("total", len(rows))
print(Counter((r["file"], r["kind"]) for r in rows))
